CREATE TABLE users(id BIGSERIAL PRIMARY KEY,subject TEXT NOT NULL UNIQUE,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,admin BOOLEAN NOT NULL DEFAULT FALSE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE auth_attempts(id BIGSERIAL PRIMARY KEY,state_hash TEXT NOT NULL UNIQUE,nonce TEXT NOT NULL,verifier TEXT NOT NULL,purpose TEXT NOT NULL,connection_id BIGINT NOT NULL DEFAULT 0,user_id BIGINT NOT NULL DEFAULT 0,binding_hash TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sessions(id BIGSERIAL PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,user_id BIGINT NOT NULL REFERENCES users(id),last_seen_at TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE connections(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,provider TEXT NOT NULL CHECK(provider IN ('gmail','jira','slack')),config JSONB NOT NULL,secret BYTEA,status TEXT NOT NULL DEFAULT 'pending',error TEXT NOT NULL DEFAULT '',history_id TEXT NOT NULL DEFAULT '',watch_expires TIMESTAMPTZ,cutover TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE flows(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,source_id BIGINT NOT NULL REFERENCES connections(id),enabled BOOLEAN NOT NULL DEFAULT FALSE,definition JSONB NOT NULL,activated_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE inboxes(id BIGSERIAL PRIMARY KEY,source_id BIGINT NOT NULL REFERENCES connections(id),message_id TEXT NOT NULL,message JSONB NOT NULL,received_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(source_id,message_id));
CREATE TABLE runs(id BIGSERIAL PRIMARY KEY,flow_id BIGINT NOT NULL REFERENCES flows(id),inbox_id BIGINT NOT NULL REFERENCES inboxes(id),source_id BIGINT NOT NULL REFERENCES connections(id),flow_name TEXT NOT NULL,message_id TEXT NOT NULL,subject TEXT NOT NULL,snapshot JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'pending',completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(flow_id,inbox_id));
CREATE TABLE steps(id BIGSERIAL PRIMARY KEY,run_id BIGINT NOT NULL REFERENCES runs(id),position INT NOT NULL,action JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INT NOT NULL DEFAULT 0,next_at TIMESTAMPTZ NOT NULL DEFAULT now(),reference TEXT NOT NULL DEFAULT '',error TEXT NOT NULL DEFAULT '',started_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(run_id,position));
CREATE TABLE notifications(id BIGSERIAL PRIMARY KEY,key TEXT NOT NULL UNIQUE,body TEXT NOT NULL,delivered BOOLEAN NOT NULL DEFAULT FALSE,attempts INT NOT NULL DEFAULT 0,next_at TIMESTAMPTZ NOT NULL DEFAULT now(),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX steps_ready ON steps(status,next_at);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE INDEX auth_attempts_expiry ON auth_attempts(expires_at);
